const search=document.querySelector('#toolSearch'),cards=[...document.querySelectorAll('.tool-card')],empty=document.querySelector('#emptyState'),toast=document.querySelector('#toast'),toggle=document.querySelector('#languageToggle');let timer,lang;
function toastMsg(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2600)}
function applyLanguage(next){lang=next;const t=copy[lang];document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=lang==='zh'?'AI SuperMall — 让想法即刻发生':'AI SuperMall — Make ideas happen';document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t[el.dataset.i18n]);document.querySelectorAll('[data-i18n-html]').forEach(el=>el.innerHTML=t[el.dataset.i18nHtml]);document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t[el.dataset.i18nPlaceholder]);document.querySelectorAll('[data-i18n-query]').forEach(el=>el.dataset.query=t[el.dataset.i18nQuery]);cards.forEach((card,i)=>card.dataset.tags=t.tags[i]);toggle.textContent=lang==='zh'?'EN':'中文';toggle.setAttribute('aria-label',lang==='zh'?'Switch to English':'切换至中文');localStorage.setItem('ai-supermall-language',lang)}
function filterTools(q){const term=q.trim().toLowerCase();let visible=0;cards.forEach(card=>{const match=!term||(`${card.dataset.tags} ${card.textContent}`).toLowerCase().includes(term);card.hidden=!match;if(match)visible++});empty.hidden=visible>0;document.querySelector('#discover').scrollIntoView({behavior:'smooth',block:'start'});if(term&&visible)toastMsg(copy[lang].found(visible))}
const stored=localStorage.getItem('ai-supermall-language');const china=['Asia/Shanghai','Asia/Urumqi','Asia/Chongqing','Asia/Harbin'].includes(Intl.DateTimeFormat().resolvedOptions().timeZone);applyLanguage(stored||(china?'zh':'en'));toggle.addEventListener('click',()=>applyLanguage(lang==='zh'?'en':'zh'));
const answer=document.querySelector('#searchAnswer'),kicker=document.querySelector('#answerKicker'),title=document.querySelector('#answerTitle'),answerCopy=document.querySelector('#answerCopy'),recommendation=document.querySelector('#answerRecommendation'),answerAction=document.querySelector('#answerAction'),followForm=document.querySelector('#followUpForm'),followInput=document.querySelector('#followUpInput'),followLabel=document.querySelector('#followUpLabel'),followSubmit=document.querySelector('#followUpSubmit'),followVoice=document.querySelector('#followUpVoice'),mainSubmit=document.querySelector('#searchForm button[type="submit"]');let conversation=[],lastAnswerLanguage='zh';
const answerLanguageFor=q=>/[\u4e00-\u9fff]/.test(q)?'zh':'en';
function setFollowLanguage(language){const zh=language==='zh';followLabel.textContent=zh?'继续追问':'Continue the conversation';followInput.placeholder=zh?'输入你的下一句问题…':'Type your next question…';followSubmit.textContent=zh?'发送':'Next';followVoice.setAttribute('aria-label',zh?'语音输入':'Voice input')}
async function askAi(query,input,language){lastAnswerLanguage=language;answer.hidden=false;followForm.hidden=true;kicker.textContent='AI SUPERMALL · AI';title.textContent=language==='zh'?'正在思考…':'Thinking…';answerCopy.textContent=language==='zh'?'正在为你准备回答。':'Preparing your answer.';recommendation.textContent='';answerAction.textContent='';input.disabled=true;mainSubmit.disabled=true;try{const response=await fetch('/api/recommend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query,language,context:conversation.slice(-4)})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed');conversation.push({question:query,answer:result.answer||''});title.textContent=result.title||query;answerCopy.textContent=result.answer||'';recommendation.textContent=result.recommendation||'';answerAction.textContent=language==='zh'?'继续追问':'Continue';setFollowLanguage(language)}catch(error){title.textContent=language==='zh'?'暂时无法回答':'Unable to answer right now';answerCopy.textContent=language==='zh'?'请稍后再试。':'Please try again shortly.';recommendation.textContent='';answerAction.textContent=''}finally{input.disabled=false;mainSubmit.disabled=false;answer.scrollIntoView({behavior:'smooth',block:'center'})}}
const goToRecommendation=event=>{event.preventDefault();const query=search.value.trim();if(!query){toastMsg(lang==='zh'?'请先输入问题。':'Please enter a question.');search.focus();return}askAi(query,search,answerLanguageFor(query))};
document.querySelector('#searchForm').addEventListener('submit',goToRecommendation);
document.querySelector('#searchForm button[type="submit"]').addEventListener('click',goToRecommendation);
answerAction.addEventListener('click',event=>{event.preventDefault();followForm.hidden=false;setFollowLanguage(lastAnswerLanguage);followInput.focus()});
followForm.addEventListener('submit',event=>{event.preventDefault();const query=followInput.value.trim();if(!query){followInput.setCustomValidity(lastAnswerLanguage==='zh'?'请输入下一句问题。':'Please enter your next question.');followInput.reportValidity();followInput.setCustomValidity('');return}askAi(query,followInput,answerLanguageFor(query));followInput.value=''});
const voiceButton=document.querySelector('#voiceButton');
const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
if(!SpeechRecognition){voiceButton.hidden=true;}else{const recognition=new SpeechRecognition();recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onstart=()=>{voiceButton.classList.add('listening');toastMsg(lang==='zh'?'正在听，请说话…':'Listening…')};recognition.onend=()=>voiceButton.classList.remove('listening');recognition.onerror=()=>toastMsg(lang==='zh'?'没有听清，请再试一次。':'I did not catch that. Please try again.');recognition.onresult=e=>{search.value=e.results[0][0].transcript;toastMsg(lang==='zh'?'已输入语音内容，请点击开始。':'Voice input added. Tap Start.');search.focus()};voiceButton.onclick=()=>{recognition.lang=lang==='zh'?'zh-CN':'en-US';recognition.start()};}
document.querySelectorAll('[data-query]').forEach(btn=>btn.addEventListener('click',()=>{search.value=btn.dataset.query;filterTools(search.value)}));document.querySelectorAll('[data-scroll]').forEach(btn=>btn.addEventListener('click',()=>document.querySelector(btn.dataset.scroll).scrollIntoView({behavior:'smooth'})));document.querySelectorAll('.try-button').forEach(btn=>btn.addEventListener('click',()=>toastMsg(copy[lang].soon(btn.closest('.tool-card').querySelector('h3').textContent))));
if(!SpeechRecognition){followVoice.hidden=true}else{const followRecognition=new SpeechRecognition();followRecognition.interimResults=false;followRecognition.maxAlternatives=1;followRecognition.onresult=e=>{followInput.value=e.results[0][0].transcript;followInput.focus()};followRecognition.onerror=()=>toastMsg(lastAnswerLanguage==='zh'?'没有听清，请再试一次。':'I did not catch that. Please try again.');followVoice.addEventListener('click',()=>{followRecognition.lang=lastAnswerLanguage==='zh'?'zh-CN':'en-US';followRecognition.start()})}
